   [3]={next_id=4, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这儿的光线更加明亮，深色的墙壁上布满了金属的纹路，还有猛兽锐利的爪痕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [4]={next_id=5, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="金属的缝隙间还有早已干涸的血迹，因为渗透太深而无法被完全清理，而打扫它的人仿佛也只是应付差事，并未仔细清理。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [5]={next_id=6, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这儿……", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [6]={next_id=7, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音充满着迟疑，甚至还有些惊惧，你顺着她的视线看过去，发觉在前边不远处，倒着一具穿着白色试验服的骸骨。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [7]={next_id=8, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="质感看起来并非是人类的骨头，但外观却与人类别无二致，深红色的锈迹在其上蔓延，露出斑驳的空洞。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [8]={next_id=9, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是奥尼弗尔的研究，他们想要将人类的意识转移给机械，但机械始终没有办法替代真正的人。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [9]={next_id=10, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特抬起头望向前方，在那片黑暗中，还堆积了更多如此的尸骸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [10]={next_id=11, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="根据我先前拿到的那些资料，奥尼弗尔效仿古代的因斐诺人，通过将修格尔的基因注射给人类的方式来进行试验。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [11]={next_id=12, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特的声音仿佛有些空洞，你没有作声，安静地站在她身畔听她诉说。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [12]={next_id=13, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但是几乎没有人类能承受住怪物的基因，这被奥尼弗尔称之为损耗，很多人都死在了实验室里。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [13]={next_id=14, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥尼弗尔将极少数的成功个体视作进化的先导，想要借此找到因斐诺残留的另一个遗迹。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [14]={next_id=15, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="克里安卡提起过，她的“母亲”希望能借助她所拥有的力量找到一座位于水下的古代城市。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [15]={next_id=16, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听你这么说，维瑟内特没有多意外。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [16]={next_id=17, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那是在因斐诺毁灭前，掌权的坎贝尔家族受到“神”的指引，举全国之力复制出来的另一座普瑞斯城，坐落于幽暗的海洋之下，据说人类与高等文明在其间共存。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [17]={next_id=18, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="据说？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [18]={next_id=19, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="因斐诺的一手资料如今已经十不存一，黎苏根地下的遗迹亦是危险重重，对它的研究更多还是停留在其他国家的相关记述中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [19]={next_id=20, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没有任何人能够证明那座城市存在，起码帮奥尼弗尔绑架女孩子的那些遗民都不能确定。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [20]={next_id=21, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但有一点是肯定的，接受了怪物基因的人类寿命会变得极其有限，因斐诺时代就没能克服这一难题。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [21]={next_id=22, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，奥尼弗尔参考因斐诺时期制造机械生命的原理，开启了另一项试验计划，我们刚刚见到的那些机器人就是这项计划的成果。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [22]={next_id=23, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="用特制的金属打造出与人类一模一样的骨骼，然后利用生物材料填充，拟做人类的血肉。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [23]={next_id=24, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你仔细回想着那些机械守卫的形貌，除去缺乏人类的外形外，行为举止都与正常人类没有任何差别。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_408.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
