   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="坎立拉事件后伊南姆家族失权，为了在拉蒂夫家族的清算中活命，不得不前来这里寻求庇护。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但被榨干剩余价值后，死于非命。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥尼弗尔在尤赞坦境内一直有人支持，之前我也听人提起过，正是因为支持者失势，奥尼弗尔才不得不采取一些别的手段去获取经济支持。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你低下头，发现这个人的大衣口袋里好像装了什么东西，于是伸手把那件东西拿了出来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是一枚古铜色的金属徽章，做成了心脏的造型，它是因斐诺时期执掌大权的坎贝尔家族的家徽，在坎贝尔家族的鼎盛时期，由第一任坎贝尔公爵托马斯·坎贝尔设计，随后作为这个家族的徽记一起存留在了历史上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你对这件东西不陌生，也清楚它的来历——瑟勒女士正是以此为线索找到了维瑟内特和莱斯坦斯，这才牵引出了克里安卡、以及奥尼弗尔的事情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="金属的徽章在手中没多少重量，釉质的涂料已经有些粗糙，似乎被留在这儿有些时间了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="（坎贝尔公爵……公爵……）", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="某些思路忽然通畅，隐约间大脑中的某些线索串联了起来，还没来得及往深里想，身后传来碰撞声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
